// === Tab: mySketch ===
const cols = 160;
const rows = 90;

const dotSpacing = 8;

// Ripple settings
const maxDistortion = 30;

let dots = [];

function setup() {

  createCanvas(1400, 900);
  smooth();

  // Center grid
  const offsetX =
    (width - cols * dotSpacing) / 2;

  const offsetY =
    (height - rows * dotSpacing) / 2;

  // Create dots
  for (let i = 0; i < cols; i++) {

    dots[i] = [];

    for (let j = 0; j < rows; j++) {

      dots[i][j] = new Dot(
        i * dotSpacing + offsetX,
        j * dotSpacing + offsetY
      );

    }
  }
}

function draw() {

  // White background
  background(255);

  const mousePosition =
    createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  // Update dots
  for (let i = 0; i < cols; i++) {

    for (let j = 0; j < rows; j++) {

      dots[i][j].update(mousePosition);

    }
  }
}

class Dot {

  constructor(x, y) {

    this.position =
      createVector(x, y);

    this.originalPosition =
      this.position.copy();

    this.velocity =
      createVector(0, 0);
  }

  update(mousePos) {

    // =========================
    // VECTOR TO CURSOR
    // =========================

    let vecToMouse =
      this.originalPosition.copy();

    vecToMouse.sub(mousePos);

    const distanceToMouse =
      vecToMouse.mag();

    // =========================
    // RIPPLE WAVE
    // =========================

    const ripple =
      sin(
        distanceToMouse * 0.04 -
        frameCount * 0.15
      );

    // Ripple fade with distance
    const falloff =
      exp(-distanceToMouse * 0.002);

    // Normalize direction
    vecToMouse.normalize();

    // Ripple displacement
    vecToMouse.mult(
      ripple *
      maxDistortion *
      falloff
    );

    // =========================
    // TARGET POSITION
    // =========================

    const targetPosition =
      createVector(
        this.originalPosition.x +
          vecToMouse.x,

        this.originalPosition.y +
          vecToMouse.y
      );

    // =========================
    // SPRING PHYSICS
    // =========================

    let attractionVector =
      targetPosition.copy();

    attractionVector.sub(
      this.position
    );

    attractionVector.mult(0.08);

    this.velocity.add(
      attractionVector
    );

    // Smooth motion
    this.velocity.mult(0.92);

    this.position.add(
      this.velocity
    );

    // =========================
    // STROKE WEIGHT
    // =========================

    const strokeWidth =
      0.15 +
      abs(ripple) * 1.2;

    // =========================
    // COLOR GRADIENT
    // =========================

    const gx = map(
      this.originalPosition.x,
      0,
      width,
      0,
      1
    );

    const gy = map(
      this.originalPosition.y,
      0,
      height,
      0,
      1
    );

    const n = noise(
      this.originalPosition.x * 0.003,
      this.originalPosition.y * 0.003,
      frameCount * 0.01
    );

    // Holographic gradient
    const r =
      180 +
      75 *
        sin(
          frameCount * 0.01 +
          gx * 5
        );

    const g =
      180 +
      75 *
        sin(
          frameCount * 0.01 +
          gy * 5
        );

    const b =
      180 +
      75 *
        sin(
          frameCount * 0.01 +
          n * 10
        );

    stroke(r, g, b);

    // =========================
    // FLOW FIELD ROTATION
    // =========================

    const angle =
      noise(
        this.position.x * 0.002,
        this.position.y * 0.002,
        frameCount * 0.002
      ) *
      TWO_PI *
      2;

    // =========================
    // DRAW
    // =========================

    push();

    translate(
      this.position.x,
      this.position.y
    );

    rotate(angle);

    strokeWeight(strokeWidth);

    // Thin flow-field line
    line(-1, 0, 1, 0);

    pop();
  }
}

// =========================
// EXPORT PNG
// Press S
// =========================

function keyPressed() {

  if (
    key === 's' ||
    key === 'S'
  ) {

    saveCanvas(
      'ripple_flowfield',
      'png'
    );
  }
}

